@pytest.mark.tc('TC_PROF_001')
def test_tc_prof_001_verify_my_profile_page_displays_all_user(app):
    """TC_PROF_001: Verify My Profile page displays all user details and export option when signed in

    Scenario: SC_PROF_001
    Expected: My Profile page loads with heading  My Profile ; display name  kk ; test account email; conversation count text; data storage notice; privacy notice; and enabled  Export selected conversation as Markdown  button.
    Note: Preconditions assume user is already signed in. Script navigates to My Profile via sidebar radio button and verifies all required elements. Email verification uses expect_visible on the email div since exact email value is not provided in t
    """
    with app.step('Open the application home page', action='goto', element=''):
        app.goto('/')
    with app.step("Select 'My Profile' in the sidebar navigation", action='click', element='home.my_profile_radio'):
        app.pages.home.my_profile_radio.click()
    with app.step('Verify the display name label is shown', action='expect_text', element='my_profile.display_name_div'):
        app.pages.my_profile.display_name_div.expect_text('Display name')
    with app.step("Verify the display name 'kk' is shown", action='expect_text', element='my_profile.display_name_textbox'):
        app.pages.my_profile.display_name_textbox.expect_text('kk')
    with app.step('Verify the email label is displayed', action='expect_visible', element='my_profile.email_div'):
        app.pages.my_profile.email_div.expect_visible()
    with app.step('Verify the test account email is displayed', action='expect_visible', element='my_profile.email_textbox'):
        app.pages.my_profile.email_textbox.expect_visible()
    with app.step('Verify the local conversation count text is present', action='expect_visible', element='my_profile.3_conversation_s_saved_to_this_app_s_lo_div'):
        app.pages.my_profile.el_3_conversation_s_saved_to_this_app_s_lo_div.expect_visible()
    with app.step('Verify the data storage notice is displayed', action='expect_text', element='my_profile.the_app_stores_account_and_conversation_div'):
        app.pages.my_profile.the_app_stores_account_and_conversation_div.expect_text('The app stores account and conversation data locally on the')
    with app.step('Verify the privacy notice is displayed', action='expect_text', element='my_profile.your_account_details_stay_separate_from_div'):
        app.pages.my_profile.your_account_details_stay_separate_from_div.expect_text('Your account details stay separate from your chat content.')
    with app.step('Verify the Export selected conversation as Markdown button is present and enabled', action='expect_enabled', element='my_profile.export_selected_conversation_as_markdown_button'):
        app.pages.my_profile.export_selected_conversation_as_markdown_button.expect_enabled()

