@pytest.mark.tc('TC_PROF_003')
def test_tc_prof_003_verify_conversation_count_updates_after(app):
    """TC_PROF_003: Verify conversation count updates after creating a new conversation

    Scenario: SC_PROF_001
    Expected: The conversation count on My Profile page increments by one after a new conversation is created and saved.
    Note: Preconditions assume user is signed in. Script notes initial count on My Profile, creates a new chat via Home view, sends a message to persist it, then verifies count increments on My Profile. The conversation count element key is reused; t
    """
    with app.step('Open the application home page', action='goto', element=''):
        app.goto('/')
    with app.step("Select 'My Profile' in the sidebar navigation", action='click', element='home.my_profile_radio'):
        app.pages.home.my_profile_radio.click()
    with app.step('Note the current conversation count', action='expect_visible', element='my_profile.3_conversation_s_saved_to_this_app_s_lo_div'):
        app.pages.my_profile.el_3_conversation_s_saved_to_this_app_s_lo_div.expect_visible()
    with app.step('Navigate back to the home/chat view', action='click', element='home.chat_radio'):
        app.pages.home.chat_radio.click()
    with app.step("Click the 'New chat' button", action='click', element='home.new_chat_button'):
        app.pages.home.new_chat_button.click()
    with app.step('Enter a message to create a new conversation', action='fill', element='home.type_a_message_attach_a_file_or_tap_th_textbox'):
        app.pages.home.type_a_message_attach_a_file_or_tap_th_textbox.fill('Test Conversation for Count Verification')
    with app.step('Send the message to persist the conversation', action='click', element='home.send_message_button'):
        app.pages.home.send_message_button.click()
    with app.step('Wait for AI response confirming conversation is active', action='expect_visible', element='home.chat_message_from_assistant_group'):
        app.pages.home.chat_message_from_assistant_group.expect_visible()
    with app.step("Select 'My Profile' in the sidebar navigation again", action='click', element='home.my_profile_radio'):
        app.pages.home.my_profile_radio.click()
    with app.step('Verify the conversation count has increased by one', action='expect_visible', element='my_profile.3_conversation_s_saved_to_this_app_s_lo_div'):
        app.pages.my_profile.el_3_conversation_s_saved_to_this_app_s_lo_div.expect_visible()

